INSERT INTO log_signal_pending(log_id) SELECT l.id FROM log_records l WHERE (l.process IN ('kernel','sshd','sshd-session') AND NOT l.truncated AND octet_length(l.message)<=8192 AND (l.message LIKE 'Out of memory: Killed process %' OR l.message LIKE 'Memory cgroup out of memory: Killed process %' OR l.message LIKE 'Failed password for %')) AND l.received_at>now()-interval '5 minutes' AND l.event_at>now()-interval '5 minutes' AND NOT EXISTS(SELECT 1 FROM log_incident_records e WHERE e.log_id=l.id) ORDER BY l.id DESC LIMIT 10000 ON CONFLICT DO NOTHING;
